package com.shopsphere.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.IOException;import java.util.UUID;import java.util.logging.Logger;
@WebFilter("/*") public class CorrelationIdFilter implements Filter{private static final Logger LOG=Logger.getLogger(CorrelationIdFilter.class.getName());public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)a;HttpServletResponse p=(HttpServletResponse)b;String id=q.getHeader("X-Request-ID");if(id==null||id.isBlank())id=UUID.randomUUID().toString();p.setHeader("X-Request-ID",id);long t=System.nanoTime();try{c.doFilter(a,b);}finally{long ms=(System.nanoTime()-t)/1000000;LOG.info(id+" "+q.getMethod()+" "+q.getRequestURI()+" "+p.getStatus()+" "+ms+"ms");}}}
